// Defensive file access: decode, normalize, then verify the jail.
const BASE = "/srv/app/content"

function safeJoin(base, requested) {
  // 1. Percent-escapes are aliases: %2e%2e is ..
  const decoded = decodeURIComponent(requested)

  // 2. Split and drop empty, current-dir and parent-dir segments.
  const segs = decoded.split("/").filter((s) => s && s !== "." && s !== "..")

  // 3. Absolute-path input must not escape the base: ignore leading slash.
  return base + "/" + segs.join("/")
}

function readContent(requested) {
  const path = safeJoin(BASE, requested)
  if (!path.startsWith(BASE + "/")) {
    // Unreachable after safeJoin, but the check documents the invariant
    // and guards future refactors.
    throw new Error("path escapes base")
  }
  return fs.readFileSync(path)
}

// Negative tests that must all pass:
//   readContent("../../etc/passwd")   -> BASE/posts/etc/passwd (harmless)
//   readContent("%2e%2e/%2e%2e/keys") -> BASE/keys (inside jail, denied by auth layer)
//   readContent("/etc/passwd")        -> BASE/etc/passwd (leading slash neutralized)
